window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dbd9d8513060834b"]={"versions": [{"id": "FIG-dbd9d8513060834b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Konfigurations-Metamodells (ECUC Parameter Configuration) des Diagnostic Event Managers (Dem) in AUTOSAR Classic Platform. Das Diagramm spezifiziert die Struktur und Parameter des Konfigurationscontainers <code>DemComponent</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Konfigurationscontainer <code>DemComponent</code> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>0..*</code>).</p>\n<p class=\"fig-p\">Aggregierte Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\"><li><code>DemComponentId</code>: Integer-Parameter (<code>EcucIntegerParamDef</code>), Multiplizität <code>1..1</code>, Wertebereich <code>min = 1</code>, <code>max = 65535</code>, <code>symbolicNameValue = true</code>.\n</li><li><code>DemComponentIgnoresPriority</code>: Boolean-Parameter (<code>EcucBooleanParamDef</code>), Multiplizität <code>0..1</code>, <code>defaultValue = false</code>.\n</li><li><code>DemComponentFailedCallbackFnc</code>: Funktionsnamen-Parameter (<code>EcucFunctionNameDef</code>), Multiplizität <code>0..1</code>.\n</li></ul>\n<p class=\"fig-p\">Aggregierte Referenzen (<code>+reference</code> / <code>+destination</code>):</p>\n<ul class=\"fig-list\"><li><code>DemImmediateChildComponentRef</code>: Referenzdefinition (<code>EcucReferenceDef</code>), Multiplizität <code>0..*</code>, verweist rekursiv auf untergeordnete Instanzen von <code>DemComponent</code> (<code>+destination</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Konfigurations- und Metamodell-Struktur. Zur Laufzeit bzw. Generierungszeit definiert <code>DemImmediateChildComponentRef</code> eine hierarchische Baumstruktur von Dem-Komponenten (übergeordnete und untergeordnete Komponenten). Bei Ausfall einer Komponente kann über <code>DemComponentFailedCallbackFnc</code> ein konfigurierter Callback aufgerufen werden, während <code>DemComponentIgnoresPriority</code> das Verhalten bezüglich Fehlerprioritäten steuert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Konfigurationsparameter für Dem-Komponenten. Konfigurations- und BSW-Generierungswerkzeuge müssen die Multiplizitäten, Wertebereiche sowie die rekursive Selbst-Referenzierung zur Modellierung von Komponenten-Hierarchien validieren und im generierten Dem-BSW-Modul abbilden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-84cf8b1e6b6c8e94", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Konfigurations-Metamodells (ECUC Parameter Configuration) des Diagnostic Event Managers (Dem) in AUTOSAR Classic Platform. Das Diagramm spezifiziert die Struktur und Parameter des Konfigurationscontainers <code>DemComponent</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Konfigurationscontainer <code>DemComponent</code> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>0..*</code>).</p>\n<p class=\"fig-p\">Aggregierte Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\"><li><code>DemComponentId</code>: Integer-Parameter (<code>EcucIntegerParamDef</code>), Multiplizität <code>1..1</code>, Wertebereich <code>min = 1</code>, <code>max = 65535</code>, <code>symbolicNameValue = true</code>.\n</li><li><code>DemComponentIgnoresPriority</code>: Boolean-Parameter (<code>EcucBooleanParamDef</code>), Multiplizität <code>0..1</code>, <code>defaultValue = false</code>.\n</li><li><code>DemComponentFailedCallbackFnc</code>: Funktionsnamen-Parameter (<code>EcucFunctionNameDef</code>), Multiplizität <code>0..1</code>.\n</li><li><code>DemComponentFailedCallbackUsePort</code>: Parameter vom Typ <code>EcucFunctionNameDef</code> (mit Boolean-Standardwert), Multiplizität <code>0..1</code>, <code>defaultValue = false</code>.\n</li></ul>\n<p class=\"fig-p\">Aggregierte Referenzen (<code>+reference</code> / <code>+destination</code>):</p>\n<ul class=\"fig-list\"><li><code>DemImmediateChildComponentRef</code>: Referenzdefinition (<code>EcucReferenceDef</code>), Multiplizität <code>0..*</code>, verweist rekursiv auf untergeordnete Instanzen von <code>DemComponent</code> (<code>+destination</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Konfigurations- und Metamodell-Struktur. Zur Laufzeit bzw. Generierungszeit definiert <code>DemImmediateChildComponentRef</code> eine hierarchische Baumstruktur von Dem-Komponenten. Bei Ausfall einer Komponente wird die Benachrichtigung entweder über die direkte C-Callback-Funktion <code>DemComponentFailedCallbackFnc</code> oder abhängig von <code>DemComponentFailedCallbackUsePort</code> über einen entsprechenden Port-Mechanismus abgewickelt, während <code>DemComponentIgnoresPriority</code> die Prioritätsbewertung steuert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Konfigurationsparameter für Dem-Komponenten. Konfigurations- und BSW-Generierungswerkzeuge müssen die Multiplizitäten, Wertebereiche sowie die Option zur Port-basierten Benachrichtigung (<code>DemComponentFailedCallbackUsePort</code>) neben <code>DemComponentFailedCallbackFnc</code> validieren und abbilden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-dbd9d8513060834b", "to": "FIG-84cf8b1e6b6c8e94", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Hinzufügung des Konfigurationsparameters <code>DemComponentFailedCallbackUsePort</code> (Typ <code>EcucFunctionNameDef</code>, Multiplizität 0..1, <code>defaultValue = false</code>) als aggregierter <code>+parameter</code> von <code>DemComponent</code>.\n</li></ul>"}]};
